// ════════════════════════════════════════════════════════════════
// Agent Spec Linter V1.0 — Deterministe — 100% Code node
// Valide la spec AVANT l'Architect pour eviter les regenerations
// ════════════════════════════════════════════════════════════════
const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body
           : (typeof raw.body === 'string') ? JSON.parse(raw.body.replace(/^=+/, '').trim()) : raw;

const task_id    = String(body.task_id || 'unknown');

// En mode amélioration : spec déjà validée lors de la génération V1 — PASS immédiat
if (body.improve_mode === true) {
  return [{ json: {
    task_id,
    linter_status:  'PASS',
    errors_count:   0,
    warnings_count: 0,
    errors:         [],
    warnings:       [],
    summary:        'PASS — Mode amélioration : spec non re-validée (déjà validée lors de la génération V1).',
    checked_at:     new Date().toISOString()
  }}];
}

const spec       = String(body.userRequest || '');
const specLower  = spec.toLowerCase();
const lines      = spec.split('\n');

const errors   = [];
const warnings = [];

// ─────────────────────────────────────────────
// Extraction des routes depuis la spec
// N'extraire un segment que s'il est explicitement annoncé par un verbe HTTP
// (ex: "POST /trajets"). Un simple token commençant par "/" dans du texte
// libre (date "03/07/2026", fraction "3/heure", ratio "1/3", URL...) n'est
// PAS une déclaration de route et ne doit pas être compté.
// ─────────────────────────────────────────────
const extractedRoutes = [];
const routeDeclRegex = /\b(GET|POST|PUT|PATCH|DELETE)\s+(\/[a-zA-Z0-9_\-\/\{\}:]+)/g;
let rdm;
while ((rdm = routeDeclRegex.exec(spec)) !== null) {
  const seg = rdm[2].slice(1).split('/')[0].replace(/[^a-zA-Z0-9_\u00C0-\u024F-]/g, '').toLowerCase();
  if (seg && !extractedRoutes.includes(seg)) extractedRoutes.push(seg);
}

// ─────────────────────────────────────────────
// REGLE P1-01 : Pas d'acteurs comme routes
// ─────────────────────────────────────────────
const ACTORS = [
  'users','user','clients','client','citoyens','citoyen','voyageurs','voyageur',
  'admin','admins','administrators','administrator','customers','customer',
  'persons','person','people','members','member','agents','agent',
  'operateurs','operateur','residents','resident','owners','owner',
  'drivers','driver','riders','rider','passagers','passager','habitants','habitant'
];
for (const r of extractedRoutes) {
  if (ACTORS.includes(r)) {
    errors.push({
      rule: 'P1-01-NO_ACTOR_ROUTES',
      message: 'Route /' + r + ' correspond a un acteur, pas une ressource metier.',
      fix: 'Utiliser la ressource metier (ex: /signalements, /trajets, /commandes). ' +
           'Les acteurs sont des utilisateurs du systeme, pas des ressources.'
    });
  }
}

// ─────────────────────────────────────────────
// REGLE P1-02 : Maximum 6 ressources déclarées explicitement
// (ne se déclenche que si la spec liste elle-même des routes avec verbe HTTP —
// une spec en prose libre, sans déclaration explicite, n'est jamais concernée)
// ─────────────────────────────────────────────
if (extractedRoutes.length > 6) {
  errors.push({
    rule: 'P1-02-MAX_6_RESOURCES',
    message: extractedRoutes.length + ' ressources declarees explicitement avec verbe HTTP. Maximum 6 (au-dela, l Architect les ignore).',
    fix: 'Conserver uniquement les 6 ressources principales: ' + extractedRoutes.slice(0,6).join(', ')
  });
}

// ─────────────────────────────────────────────
// REGLE P1-03 : project_name present et valide
// ─────────────────────────────────────────────
let projectName = null;
for (const line of lines) {
  const l = line.toLowerCase().replace(/\s+/g,' ').trim();
  const isProjectLine = l.startsWith('project_name') || l.startsWith('nom du projet') || l.startsWith('application :') || l.startsWith('application:');
  if (isProjectLine) {
    // Essayer séparateur : ou | (format markdown/YAML)
    const colonIdx = line.indexOf(':');
    const pipeIdx  = line.indexOf('|');
    const sep = colonIdx > 0 ? colonIdx : (pipeIdx > 0 ? pipeIdx : -1);
    if (sep > 0) {
      const val = line.slice(sep+1).trim();
      if (val.length > 0) { projectName = val; break; }
    }
    // Fallback : format table PDF — valeur après le mot-clé (séparée par espaces)
    const keywords = ['project_name', 'nom du projet', 'application'];
    for (const kw of keywords) {
      if (l.startsWith(kw)) {
        const remainder = line.slice(kw.length).replace(/^[\s:]+/, '').trim();
        if (remainder.length > 0) { projectName = remainder; break; }
      }
    }
    if (projectName) break;
  }
}
if (!projectName && lines.length > 0) {
  // Chercher un header markdown "# NomProjet"
  const firstHeader = lines.find(l => l.trim().startsWith('#'));
  if (firstHeader) projectName = firstHeader.replace(/^#+\s*/, '').trim();
}
if (!projectName && lines.length > 0) {
  // Chercher "Nom du projet" sur une ligne, valeur sur la ligne suivante (format tableau multi-lignes)
  for (let i = 0; i < lines.length - 1; i++) {
    const l = lines[i].toLowerCase().replace(/\s+/g,' ').trim();
    if (l === 'nom du projet' || l === 'project_name') {
      const next = lines[i+1].trim();
      if (next.length > 0 && next.length < 50) { projectName = next; break; }
    }
  }
}
if (!projectName && lines.length > 0) {
  // Dernier repli : premiere ligne non vide du document, si elle ressemble a un titre
  // (document PDF reel sans balisage markdown ni label explicite — cas frequent en pratique).
  const GENERIC_PREAMBLE_WORDS = ['specifications','specification','document','template','doc',
    'rapport','report','fichier','forge','test','projet','project','note','cahier','brief',
    'confidentiel','version','draft','brouillon'];
  const firstNonEmpty = lines.find(l => l.trim().length > 0);
  if (firstNonEmpty) {
    const candidate = firstNonEmpty.trim();
    const firstWord = candidate.split(/[\s\-_:]+/)[0].toLowerCase().replace(/[^a-z]/g,'');
    if (candidate.length > 1 && candidate.length < 50 && !GENERIC_PREAMBLE_WORDS.includes(firstWord)) {
      projectName = candidate;
    }
  }
}
if (!projectName) {
  errors.push({
    rule: 'P1-03-PROJECT_NAME_MISSING',
    message: 'project_name introuvable dans la spec.',
    fix: 'Ajouter "project_name: NomApp" en debut de document (1-3 mots, sans caracteres speciaux). ' +
         'Ce champ est utilise comme titre README et nom du ZIP genere.'
  });
} else {
  const forbidden = projectName.split('').filter(c => {
    const code = c.charCodeAt(0);
    return !(
      (code >= 65 && code <= 90) || (code >= 97 && code <= 122) ||
      (code >= 48 && code <= 57) || c === '_' || c === '-' || c === ' ' ||
      (code >= 0xC0 && code <= 0x024F)
    );
  });
  if (forbidden.length > 0) {
    errors.push({
      rule: 'P1-03-PROJECT_NAME_INVALID_CHARS',
      message: 'project_name "' + projectName + '" contient des caracteres interdits: ' + [...new Set(forbidden)].join(''),
      fix: 'Utiliser uniquement lettres, chiffres, tirets et underscores dans project_name'
    });
  }
}

// ─────────────────────────────────────────────
// REGLE P1-04 : Champs FK se terminent par _id
// ─────────────────────────────────────────────
const allWords = spec.split(/[\s,|;:()\[\]{}\n\r"']+/).map(w => w.trim()).filter(Boolean);
for (const w of allWords) {
  if (w.length < 3) continue;
  if (w.endsWith('_ref') || w.endsWith('_reference')) {
    const suggested = w.replace(/_ref$|_reference$/i, '_id');
    errors.push({
      rule: 'P1-04-FK_NAMING_REF',
      message: 'Champ "' + w + '" est une FK mais ne se termine pas par _id.',
      fix: 'Renommer en "' + suggested + '"'
    });
  }
  if (w.endsWith('Id') && w.length > 2 && w[0] === w[0].toLowerCase()) {
    const suggested = w.replace(/Id$/, '_id');
    warnings.push({
      rule: 'P1-04-FK_CAMELCASE',
      message: 'Champ "' + w + '" utilise camelCase. Preferer snake_case.',
      fix: 'Renommer en "' + suggested + '"'
    });
  }
}

// ─────────────────────────────────────────────
// REGLE P1-05 : Pas d'accents dans les noms de routes
// ─────────────────────────────────────────────
for (const r of extractedRoutes) {
  const hasAccent = r.split('').some(c => { const code = c.charCodeAt(0); return code >= 0xC0 && code <= 0x024F; });
  if (hasAccent) {
    errors.push({
      rule: 'P1-05-ACCENTS_IN_ROUTES',
      message: 'Route /' + r + ' contient des caracteres non-ASCII. Les URLs doivent etre en ASCII pur.',
      fix: 'Translitterer: /reservations, /historique, /reclamations (sans accents)'
    });
  }
}

// ─────────────────────────────────────────────
// REGLE P1-06 : Au moins une ressource
// ─────────────────────────────────────────────
if (extractedRoutes.length === 0) {
  // Warning seulement : certains specs valides (DiaspoKoli, specs narratifs)
  // ne listent pas de routes explicites mais l'Architect sait les extraire
  warnings.push({
    rule: 'P2-NO_EXPLICIT_ROUTES',
    message: 'Aucune route /xxx detectee dans la spec. Le pipeline peut continuer si les ressources sont decrites textuellement.',
    fix: 'Optionnel : ajouter des routes explicites (ex: /signalements) pour une meilleure lisibilite'
  });
}

// ─────────────────────────────────────────────
// REGLE P2 : Types non supportes (warnings)
// ─────────────────────────────────────────────
const UNSUPPORTED_TYPES = ['boolean','bool','array','object','date','datetime','integer','float','decimal','blob','binary'];
const seenTypes = new Set();
for (const t of UNSUPPORTED_TYPES) {
  if (!seenTypes.has(t)) {
    // Vérifier que le mot apparaît comme déclaration de type, pas dans une description
    // Patterns valides : "type: date", "| date |", "type date", ": date,"
    const typeAsDecl = new RegExp('(?:type[\\s:=]+|\\|\\s*|:\\s*)' + t + '(?:\\s*[\\|,;\\n\\r]|\\s*$)', 'i');
    if (typeAsDecl.test(spec)) {
      seenTypes.add(t);
      warnings.push({
        rule: 'P2-TYPE_UNSUPPORTED',
        message: 'Type "' + t + '" detecte comme declaration de type. Non supporte par le pipeline (string et number uniquement).',
        fix: 'Remplacer par string ou number selon le cas'
      });
    }
  }
}

// ─────────────────────────────────────────────
// REGLE P2 : Fonctionnalites non supportees
// ─────────────────────────────────────────────
const UNSUPPORTED_FEATURES = {
  'postgresql': 'BDD PostgreSQL', 'mysql': 'BDD MySQL',
  'mongodb': 'MongoDB', 'sqlite': 'SQLite',
  'jwt': 'auth JWT', 'oauth': 'OAuth',
  'authentication': 'authentification',
  'jest': 'tests Jest', 'mocha': 'tests Mocha'
};
for (const [term, label] of Object.entries(UNSUPPORTED_FEATURES)) {
  if (specLower.includes(term)) {
    warnings.push({
      rule: 'P2-UNSUPPORTED_FEATURE',
      message: '"' + label + '" detecte. Non supporte dans le pipeline actuel.',
      fix: 'Deplacer dans la section Roadmap ou retirer de la spec'
    });
  }
}

// ─────────────────────────────────────────────
// RÈGLES P1-D : Densité minimale (Option A Sprint 1)
// ─────────────────────────────────────────────

// P1-D1 : Spec trop courte
if (spec.trim().length < 150) {
  errors.push({
    rule: 'P1-D1-SPEC_TOO_SHORT',
    message: 'Spec trop courte (' + spec.trim().length + ' caractères — minimum 150). Le pipeline ne peut pas générer une app correcte depuis une spec insuffisante.',
    fix: 'Décrire au minimum : nom du projet, 2-3 ressources avec leurs champs (string/number), et les routes CRUD attendues.'
  });
}

// P1-D2 : Trop peu de champs typés
// Comptage des déclarations "nom: type" ou "| type |" dans le texte
const fieldTypeDecls = (spec.match(/ (string|number|text|int|float|real) /gi) || []).length;
const resourceCount  = Math.max(extractedRoutes.length, 1);
if (spec.trim().length >= 150 && fieldTypeDecls < resourceCount * 2) {
  warnings.push({
    rule: 'P1-D2-FEW_TYPED_FIELDS',
    message: fieldTypeDecls + ' déclaration(s) de type détectée(s) pour ' + resourceCount + ' ressource(s). Le Normalizer risque de tomber en fallback déterministe avec des champs génériques.',
    fix: 'Ajouter les types explicites : "description: string", "prix: number", "statut: string".'
  });
}

// P1-D3 : Aucune règle métier détectable
const hasValidationKeywords = /validat|règle|rule|must|doit|entre\s+\-?\d|between|minimum|maximum|parmi\s*:|among|requis|required|supérieur|inférieur|au moins|at least|format/i.test(spec);
if (!hasValidationKeywords && spec.trim().length >= 150 && extractedRoutes.length >= 2) {
  warnings.push({
    rule: 'P1-D3-NO_BUSINESS_RULES',
    message: 'Aucune règle métier détectée (validations, contraintes, valeurs acceptées). Le backend généré n\'aura que des validations de base.',
    fix: 'Ajouter des règles : "latitude entre -90 et 90", "statut parmi : actif, inactif", "prix doit être positif".'
  });
}

// P1-D4 : Spec riche mais aucune route explicite (spec narrative/DiaspoKoli-like)
// → Downgrader en warning informatif seulement, pas bloquant
// (déjà couvert par P2-NO_EXPLICIT_ROUTES)

const linter_status = errors.length > 0 ? 'FAIL' : 'PASS';

return [{
  json: {
    task_id,
    linter_status,
    errors_count:   errors.length,
    warnings_count: warnings.length,
    errors,
    warnings,
    summary: linter_status === 'FAIL'
      ? 'FAIL — ' + errors.length + ' erreur(s) bloquante(s). Corrigez la spec avant relance.'
      : 'PASS — Spec valide' + (warnings.length > 0 ? ' (' + warnings.length + ' warning(s))' : '.'),
    checked_at: new Date().toISOString()
  }
}];
